const parse = function vectorRequest({ query }) {
  if (typeof query.vectors !== 'string' || !query.vectors) return { vectors: null, error: 'Invalid input: Expected an array of vectors.' };
  try {
    let nonFinite = false;
    const vectors = JSON.parse(query.vectors, (_key, value) => {
      if (typeof value === 'number' && !Number.isFinite(value)) nonFinite = true;
      return value;
    });
    if (nonFinite) return { vectors: null, error: 'Vectors must contain finite numbers.' };
    return { vectors, error: null };
  }
  catch { return { vectors: null, error: 'Invalid input: vectors must be valid JSON.' }; }
}

return {json:parse({query:$json.query})};

const calculate = function vectorCentroid({ vectors, error }) {
  const fail = (error) => ({ result: { error } });
  if (error) return fail(error);
  if (!Array.isArray(vectors) || vectors.length === 0) return fail('Invalid input: Expected an array of vectors.');
  if (!vectors.every(Array.isArray)) return fail('Each vector must be an array.');
  const dimension = vectors[0].length;
  if (!vectors.every((vector) => vector.length === dimension)) return fail('Vectors have inconsistent dimensions.');
  if (!vectors.every((vector) => vector.every((value) => typeof value === 'number' && Number.isFinite(value)))) return fail('Vectors must contain finite numbers.');
  const centroid = Array.from({ length: dimension }, (_, index) => {
    let scale = 0;
    for (const vector of vectors) scale = Math.max(scale, Math.abs(vector[index]));
    if (scale === 0) return 0;
    let sum = 0, correction = 0;
    for (const vector of vectors) {
      const adjusted = vector[index] / scale - correction;
      const next = sum + adjusted;
      correction = (next - sum) - adjusted;
      sum = next;
    }
    return (sum / vectors.length) * scale;
  });
  if (!centroid.every(Number.isFinite)) return fail('Centroid exceeds the finite numeric range.');
  return { result: { centroid } };
}

return {json:calculate($json).result};
